import React from 'react';
import { PlayCircle, PauseCircle, Wrench, AlertTriangle, Gauge, Award, Zap } from 'lucide-react';

const SystemStatusBar = () => {
  const kpis = [
    {
      title: 'Running Machines',
      value: '16 / 20',
      status: '90% Operating',
      icon: PlayCircle,
      color: '#22C55E',
      bg: '#DCFCE7',
    },
    {
      title: 'Idle Machines',
      value: '2',
      status: 'Standby Mode',
      icon: PauseCircle,
      color: '#F59E0B',
      bg: '#FEF3C7',
    },
    {
      title: 'Maintenance',
      value: '2',
      status: 'Scheduled Service',
      icon: Wrench,
      color: '#F97316',
      bg: '#FFEDD5',
    },
    {
      title: 'Critical Alerts',
      value: '3',
      status: 'Requires Action',
      icon: AlertTriangle,
      color: '#EF4444',
      bg: '#FEE2E2',
    },
    {
      title: "Today's Production",
      value: '14,250 m',
      status: 'Target 16,000 m (89%)',
      icon: Gauge,
      color: '#2563EB',
      bg: '#DBEAFE',
    },
    {
      title: 'OEE',
      value: '96.4%',
      status: 'World Class',
      icon: Award,
      color: '#8B5CF6',
      bg: '#F3E8FF',
    },
    {
      title: 'Energy Load',
      value: '1,245 kWh',
      status: 'Optimal Consumption',
      icon: Zap,
      color: '#10B981',
      bg: '#ECFDF5',
    },
  ];

  return (
    <div
      style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fit, minmax(140px, 1fr))',
        gap: '0.85rem',
        marginBottom: '1.25rem',
      }}
    >
      {kpis.map((kpi, idx) => {
        const Icon = kpi.icon;
        return (
          <div
            key={idx}
            style={{
              background: '#ffffff',
              borderRadius: '10px',
              padding: '0.85rem 1rem',
              border: '1px solid #E2E8F0',
              boxShadow: '0 2px 6px rgba(0,0,0,0.02)',
              display: 'flex',
              alignItems: 'center',
              gap: '0.75rem',
            }}
          >
            <div
              style={{
                width: '36px',
                height: '36px',
                borderRadius: '8px',
                background: kpi.bg,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                color: kpi.color,
                flexShrink: 0,
              }}
            >
              <Icon size={18} />
            </div>

            <div style={{ display: 'flex', flexDirection: 'column' }}>
              <span style={{ fontSize: '0.7rem', fontWeight: '800', color: '#64748B', textTransform: 'uppercase', letterSpacing: '0.2px' }}>
                {kpi.title}
              </span>
              <span style={{ fontSize: '1.05rem', fontWeight: '900', color: '#0F172A', lineHeight: '1.2' }}>
                {kpi.value}
              </span>
              <span style={{ fontSize: '0.68rem', fontWeight: '700', color: kpi.color, marginTop: '1px' }}>
                {kpi.status}
              </span>
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default SystemStatusBar;
